package com.lanftp;

/** Self-contained browser client: no CDN, cloud service, stored password or file-sized buffers. */
final class WebUi {
  static final String PAGE =
      """
<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>手机文件 · 局域网共享</title><style>
:root{color-scheme:light;--ink:#182d43;--muted:#637489;--blue:#185de2;--line:#e1e8f0}*{box-sizing:border-box}[hidden]{display:none!important}body{margin:0;background:#f3f6fb;color:var(--ink);font:16px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:1050px;margin:auto;padding:32px 22px}header{display:flex;gap:16px;justify-content:space-between;align-items:center}small,.muted{color:var(--muted)}h1{font-size:29px;margin:8px 0}a{color:var(--blue);text-decoration:none}button,.btn{cursor:pointer;border:1px solid var(--line);border-radius:10px;padding:11px 16px;color:var(--ink);background:white;font:inherit;display:inline-block}button:disabled{opacity:.45;cursor:default}.primary{background:var(--blue);border-color:var(--blue);color:white}.toolbar{display:flex;gap:9px;flex-wrap:wrap;margin:22px 0 12px;align-items:center}input[type=search]{min-width:120px;flex:1;border:1px solid var(--line);border-radius:10px;padding:12px;font:inherit}#path{overflow-wrap:anywhere;margin:18px 0}#status{white-space:pre-wrap;overflow-wrap:anywhere;background:#e9effb;padding:13px 16px;border-radius:10px;min-height:46px}#status.error{background:#fff0ed;color:#a42616}.card{background:white;border:1px solid var(--line);border-radius:14px;overflow:hidden;margin-top:16px}.row{display:flex;gap:14px;align-items:center;padding:16px;border-bottom:1px solid var(--line)}.row:last-child{border:0}.name{flex:1;min-width:0;overflow-wrap:anywhere}.name a{display:block;padding:4px 0}.meta{font-size:13px;color:var(--muted);margin-top:6px}.icon{font-size:25px}.delete{color:#ad3525;font-size:14px;padding:8px 10px}.empty{text-align:center;padding:48px 18px;color:var(--muted)}footer{margin:22px 0;color:var(--muted);font-size:13px;line-height:1.7}progress{width:100%;height:14px;margin-top:12px}#cancel{margin-top:8px}#upload{display:none}@media(max-width:550px){main{padding:20px 13px}h1{font-size:24px}header{align-items:flex-start}.row{gap:10px;padding:13px}.toolbar button{padding:10px 12px}}
</style><main><header><div><small>LAN / FILE SHARING</small><h1>手机文件</h1><small id="identity">正在连接手机…</small></div><a class="btn" href="/account">账号登录</a></header>
<div class="toolbar"><button id="up">上一级</button><button id="refresh">刷新</button><input id="search" type="search" placeholder="筛选当前文件夹" aria-label="筛选文件"><button id="mkdir" hidden>新建文件夹</button><button class="primary" id="pick" hidden>上传文件</button><input id="upload" type="file" multiple></div>
<div id="path"></div><div id="status" role="status" aria-live="polite">正在读取共享目录…</div><progress id="progress" max="100" value="0" hidden></progress><button id="cancel" hidden>取消上传</button><div id="list" class="card"></div>
<footer>文件来自手机授权的共享目录。点击文件即可下载；iPad 可从 Safari 下载列表保存到“文件”App。上传、覆盖和删除直接修改手机文件，删除不会进入回收站。请保持手机共享服务运行。</footer></main><script>
'use strict';
const $=id=>document.getElementById(id);let current='/',entries=[],canWrite=false,busy=false,activeUpload=null;
const api=(route,path)=>route+'?path='+encodeURIComponent(path);
function message(text,error=false){$('status').textContent=text;$('status').classList.toggle('error',error);}
function join(name){return (current==='/'?'':current)+'/'+name;}
function size(n){if(n<1024)return n+' B';let units=['KB','MB','GB','TB'],i=-1;do{n/=1024;i++;}while(n>=1024&&i<3);return n.toFixed(n<10?1:0)+' '+units[i];}
async function response(r){let data;try{data=await r.json();}catch(e){throw Error('连接中断或服务器响应无效，请检查手机上的共享状态');}if(!r.ok)throw Error(data.error||('请求失败：HTTP '+r.status));return data;}
function controls(){for(const id of ['up','refresh','mkdir','pick'])$(id).disabled=busy; $('up').disabled=busy||current==='/';}
async function load(path=current){if(busy)return;busy=true;controls();try{const data=await response(await fetch(api('/api/list',path),{cache:'no-store'}));current=data.path;entries=data.entries;canWrite=data.writable;$('identity').textContent=(data.guest?'匿名访问':'账号访问')+' · '+(canWrite?'可上传、覆盖、删除':'只读');$('pick').hidden=$('mkdir').hidden=!canWrite;$('path').textContent='共享目录 '+current;render();message(entries.length+' 项 · '+(canWrite?'可读写':'只读'));}catch(e){message(e.message,true);}finally{busy=false;controls();}}
function render(){const list=$('list');list.replaceChildren();const q=$('search').value.toLocaleLowerCase();const items=entries.filter(e=>e.name.toLocaleLowerCase().includes(q)).sort((a,b)=>Number(b.directory)-Number(a.directory)||a.name.localeCompare(b.name));if(!items.length){const empty=document.createElement('div');empty.className='empty';empty.textContent=entries.length?'没有匹配的文件':'此文件夹为空';list.append(empty);return;}for(const entry of items){const row=document.createElement('div');row.className='row';const icon=document.createElement('span');icon.className='icon';icon.textContent=entry.directory?'📁':'📄';const name=document.createElement('div');name.className='name';const link=document.createElement('a');link.textContent=entry.name;const path=join(entry.name);link.href=entry.directory?'#':api('/api/file',path);link.onclick=event=>{if(busy){event.preventDefault();return;}if(entry.directory){event.preventDefault();load(path);}};if(!entry.directory)link.download=entry.name;name.append(link);const meta=document.createElement('div');meta.className='meta';meta.textContent=(entry.directory?'文件夹':size(entry.size))+(entry.modified>0?' · '+new Date(entry.modified).toLocaleString():'');name.append(meta);row.append(icon,name);if(canWrite){const del=document.createElement('button');del.textContent='删除';del.className='delete';del.onclick=()=>remove(entry,path);row.append(del);}list.append(row);}}
async function mutate(method,path,route){return response(await fetch(api(route,path),{method,headers:{'X-LanFTP-Request':'1'}}));}
async function remove(entry,path){if(busy)return;if(!confirm('从手机永久删除“'+entry.name+'”？'+(entry.directory?'仅允许删除空文件夹。':'')))return;busy=true;controls();try{await mutate('DELETE',path,'/api/file');busy=false;await load();}catch(e){message(e.message,true);}finally{busy=false;controls();}}
$('up').onclick=()=>load(current.substring(0,current.lastIndexOf('/'))||'/');$('refresh').onclick=()=>load();$('search').oninput=render;
$('mkdir').onclick=async()=>{if(busy)return;const name=prompt('新文件夹名称');if(!name)return;if(name==='.'||name==='..'||/[\\\\/\\x00-\\x1f]/.test(name)){message('名称不能包含斜线或控制字符',true);return;}busy=true;controls();try{await mutate('POST',join(name),'/api/mkdir');busy=false;await load();}catch(e){message(e.message,true);}finally{busy=false;controls();}};
$('pick').onclick=()=>$('upload').click();$('cancel').onclick=()=>{if(activeUpload)activeUpload.abort();};
function upload(file,overwrite,index,total){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();activeUpload=xhr;xhr.open('PUT',api('/api/file',join(file.name))+(overwrite?'&overwrite=1':''));xhr.setRequestHeader('X-LanFTP-Request','1');xhr.upload.onprogress=e=>{if(e.lengthComputable){$('progress').value=e.loaded/e.total*100;message('上传 '+index+'/'+total+'：'+file.name+' · '+Math.round(e.loaded/e.total*100)+'%');}};xhr.onload=()=>{activeUpload=null;let result;try{result=JSON.parse(xhr.responseText);}catch(e){reject(Error('上传响应无效，请刷新并检查手机文件'));return;}if(xhr.status>=200&&xhr.status<300)resolve();else reject(Error(result.error||('上传失败：HTTP '+xhr.status)));};xhr.onerror=()=>{activeUpload=null;reject(Error('网络中断，请刷新并检查是否有未完成文件'));};xhr.onabort=()=>{activeUpload=null;reject(Error('已取消上传，请检查手机上的未完成文件'));};xhr.send(file);});}
$('upload').onchange=async()=>{const files=Array.from($('upload').files);$('upload').value='';if(busy||!files.length)return;busy=true;controls();message('正在准备上传…');$('progress').hidden=$('cancel').hidden=false;let completed=0,failure='';try{for(let i=0;i<files.length;i++){const file=files[i];if(/[\\\\/\\x00-\\x1f]/.test(file.name))throw Error('文件名包含不支持的字符');const exists=entries.some(e=>e.name===file.name);if(exists&&!confirm('手机已有“'+file.name+'”，是否覆盖？覆盖会立即改写原文件。'))continue;await upload(file,exists,i+1,files.length);entries=entries.filter(e=>e.name!==file.name);entries.push({name:file.name,directory:false,size:file.size,modified:Date.now()});completed++;}}catch(e){failure=e.message;}finally{busy=false;$('progress').hidden=$('cancel').hidden=true;await load();message('已上传 '+completed+' 个文件'+(failure?'。'+failure:''),!!failure);controls();}};
load();
</script></html>
""";
}
